export const sectionCategories: CategoryInfo[] = sectionCategoriesMap.map((s) => ({
  slug: s.slug,
  name: s.name,
  nameAr: s.nameAr,
  description: s.description,
  descriptionAr: s.descriptionAr,
  icon: s.icon,
  productCount: products.filter((p) => p.categorySlug && s.children.includes(p.categorySlug)).length,
}));

const sectionChildren: Record<string, string[]> = sectionCategoriesMap.reduce(
  (acc, s) => {
    acc[s.slug] = s.children;
    return acc;
  },
  {} as Record<string, string[]>
);

export function getProductBySlug(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug);
}

export function getProductsByCategory(categorySlug: string): Product[] {
  const children = sectionChildren[categorySlug];
  if (children) return products.filter((p) => p.categorySlug && children.includes(p.categorySlug));
  return products.filter((p) => p.categorySlug === categorySlug);
}

export function getCategoryBySlug(slug: string): CategoryInfo | undefined {
  return categories.find((c) => c.slug === slug) ?? sectionCategories.find((c) => c.slug === slug);
}

export function getFeaturedProducts(): Product[] {
  return products.filter((p) => p.isFeatured);
}

export function getNewArrivals(): Product[] {
  return products.filter((p) => p.isNew).slice(0, 12);
}

export function getBestSellers(): Product[] {
  return products.filter((p) => p.isBestSeller).slice(0, 12);
}

export function getDoctorRecommended(): Product[] {
  return products.filter((p) => p.isDoctorRecommended).slice(0, 8);
}

export function getRelatedProducts(product: Product, count: number = 4): Product[] {
  return products
    .filter((p) => p.id !== product.id && (p.categorySlug === product.categorySlug || p.brand === product.brand))
    .slice(0, count);
}

export function searchProducts(query: string): Product[] {
  const q = query.toLowerCase().trim();
  if (!q) return [];
  return products.filter(
    (p) =>
      p.name.ar.includes(q) ||
      p.name.en.toLowerCase().includes(q) ||
      p.brand.toLowerCase().includes(q) ||
      (p.brandAr && p.brandAr.includes(q)) ||
      (p.categoryAr && p.categoryAr.includes(q)) ||
      p.description.ar.includes(q) ||
      p.description.en.toLowerCase().includes(q)
  );
}

